UPDATE products SET sections = '[{"title": "Patru unelte, un singur set", "image": "/img/set-camping-2.jpg", "text": "Lopată, topor, fierăstrău și cuțit, toate într-un singur pachet. În loc să cari mai multe unelte separate, iei un singur set care face față celor mai multe situații din aer liber.\n\nE potrivit pentru camping, drumeții, pescuit, grădină sau ca set de rezervă în portbagaj."}, {"title": "Schimbi accesoriul în câteva secunde", "image": "/img/set-camping-3.jpg", "text": "Toate accesoriile se montează pe același mâner. Ai nevoie să sapi? Folosești lopata. Trebuie să tai o creangă? Pui fierăstrăul. La fel de simplu treci la topor sau la cuțit.\n\nMânerul are un manșon antiderapant, pentru o priză sigură."}, {"title": "Dimensiuni gândite pentru drum", "image": "/img/set-camping-5.jpg", "text": "Asamblat cu lopata are 47 cm, iar lopata are 12 × 17 cm. Cu toporul are 35 cm, cu fierăstrăul 51,5 cm, iar cu cuțitul 41 cm.\n\nSuficient de mare ca să fie util, suficient de mic ca să încapă în rucsac."}, {"title": "Totul la locul lui, în husă", "image": "/img/set-camping-6.jpg", "text": "Setul vine cu o husă de transport cu model camuflaj, în care intră toate piesele. Se închide cu capsă și se prinde de curea sau de rucsac.\n\nAșa nu pierzi nicio piesă, iar lamele stau protejate când nu le folosești."}]', specs = '[{"k": "Tip", "v": "Set multifuncțional pentru camping și outdoor"}, {"k": "Conține", "v": "Lopată cu mâner, topor, fierăstrău, cuțit, husă de transport"}, {"k": "Lungime cu lopată", "v": "47 cm"}, {"k": "Dimensiuni lopată", "v": "12 × 17 cm"}, {"k": "Lungime cu topor", "v": "35 cm"}, {"k": "Lungime cu fierăstrău", "v": "51,5 cm (lamă 16 cm)"}, {"k": "Lungime cu cuțit", "v": "41 cm (lamă 15,5 cm)"}, {"k": "Husă", "v": "Model camuflaj, cu capsă și prindere pe curea"}, {"k": "Recomandat pentru", "v": "Camping, drumeții, pescuit, grădină, portbagaj auto"}, {"k": "Atenție", "v": "Conține lame ascuțite. Nu este destinat copiilor."}]', fulfillment = 'helpship', length_cm = 50, width_cm = 20, height_cm = 8
